def strip(s):
    s=unicodedata.normalize('NFD',s)
    return ''.join(c for c in s if unicodedata.category(c)!='Mn').lower()

# index register by 3-gram of tokens
idx=collections.defaultdict(set)
for i,e in enumerate(reg):
    names=[e['primary_name']]+[a['name'] for a in e['aliases']]
    for n in names:
        for t in re.split(r'[^0-9A-Za-zЀ-ӿ؀-ۿ]+',strip(n)):
            if len(t)>=3:
                for k in range(len(t)-2):
                    idx[t[k:k+3]].add(i)

def cands(name):
    sc=collections.Counter()
    toks=[t for t in re.split(r'[^0-9A-Za-z]+',strip(name)) if len(t)>=3]
    for t in toks:
        for k in range(len(t)-2):
            for i in idx[t[k:k+3]]: sc[i]+=1
    return [reg[i] for i,_ in sc.most_common(3)]

