import json, collections, unicodedata, re, csv, itertools, sys
reg=json.load(open('/app/register.json'))
PART={'al','el','bin','ibn','ben','b','abu','abd','van','der','de','la','ad','ar','as','at','az','le','du','dos','da','von','the','bint','abdul'}
def norm(s):
    s=unicodedata.normalize('NFD',s)
    s=''.join(c for c in s if unicodedata.category(c)!='Mn')
    return s.lower()
def toks(s):
    s=norm(s).replace('-',' ')
    return [t for t in re.split(r"[^0-9a-zЀ-ӿ؀-ۿ']+",s) if t]
def core(s):
    return [t for t in toks(s) if t not in PART and len(t)>1]

def lcp(a,b):
    n=0
    while n<len(a) and n<len(b) and a[n]==b[n]: n+=1
    return n
def sim(a,b):
    # crude similarity
    if a==b: return 10
    return lcp(a,b)*2 - abs(len(a)-len(b))

def best_align(A,B):
    """return list of (a,b) aligned pairs, or None"""
    if len(A)==len(B):
        s1=sum(sim(a,b) for a,b in zip(A,B))
        # try reversed order
        best=(s1,list(zip(A,B)))
        for perm in itertools.permutations(range(len(B))):
            s=sum(sim(A[i],B[perm[i]]) for i in range(len(A)))
            if s>best[0]: best=(s,[(A[i],B[perm[i]]) for i in range(len(A))])
        return best[1]
    # merge adjacent on longer side
    if len(A)>len(B): A,B=B,A
    # now len(A)<len(B); try merging in B
    n,m=len(A),len(B)
    # choose cut points
    best=None
    for cuts in itertools.combinations(range(1,m),n-1):
        idx=[0]+list(cuts)+[m]
        merged=[''.join(B[idx[i]:idx[i+1]]) for i in range(n)]
        for perm in itertools.permutations(range(n)):
            s=sum(sim(A[i],merged[perm[i]]) for i in range(n))
            if best is None or s>best[0]: best=(s,[(A[i],merged[perm[i]]) for i in range(n)])
    return best[1] if best else None

pairs=collections.Counter()
def add(n1,n2):
    A,B=core(n1),core(n2)
    if not A or not B: return
    if abs(len(A)-len(B))>2 or max(len(A),len(B))>6: return
    al=best_align(A,B)
    if not al: return
    for x,y in al:
        if x!=y: pairs[tuple(sorted((x,y)))]+=1

for e in reg:
    if e['type']!='individual': continue
    names=[e['primary_name']]+[a['name'] for a in e['aliases'] if a['strength']=='strong']
    if e['script_name']: names.append(e['script_name'])
    for i in range(len(names)):
        for j in range(i+1,len(names)):
            add(names[i],names[j])

recs={r['record_id']:r for r in csv.DictReader(open('/app/dev/records_dev.csv'))}
R={e['uid']:e for e in reg}
for l in csv.DictReader(open('/app/dev/labels_dev.csv')):
    if l['expected_decision']!='MATCH': continue
    e=R[l['expected_uid']]
    if e['type']!='individual': continue
    rn=recs[l['record_id']]['full_name']
    # choose the entry name with closest token count
    names=[e['primary_name']]+[a['name'] for a in e['aliases'] if a['strength']=='strong']
    if e['script_name']: names.append(e['script_name'])
    names.sort(key=lambda n: abs(len(core(n))-len(core(rn))))
    add(rn,names[0])

par={}
def find(x):
    par.setdefault(x,x)
    while par[x]!=x: par[x]=par[par[x]]; x=par[x]
    return x
def uni(a,b):
    ra,rb=find(a),find(b)
    if ra!=rb: par[ra]=rb
for (a,b) in pairs: uni(a,b)
cl=collections.defaultdict(set)
for x in par: cl[find(x)].add(x)
cls=sorted(cl.values(), key=lambda s:(-len(s),sorted(s)[0]))
print('pairs',len(pairs),'classes',len(cls))
json.dump([sorted(c) for c in cls], open('/app/work/classes.json','w'), ensure_ascii=False, indent=0)
for c in cls: print(sorted(c))
